"""Single-experiment review workspace rendered by the local Research Hub."""

from __future__ import annotations

import json
from html import escape
from typing import Any


def render_experiment_page(
    experiment: dict[str, Any],
    *,
    live: bool = True,
    base_path: str = "",
) -> str:
    """Render one complete report/editor page for a discovered bundle.

    The page keeps the bundle's HTML as the full-report view, while the
    responsibility-repository Markdown is the editable source.  Images,
    videos and nested HTML are served through the Hub's range-capable route.
    """

    normalized_base = "/" + base_path.strip("/") if base_path.strip("/") else ""
    payload = json.dumps(experiment, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    mode = "live" if live else "static"
    page = _TEMPLATE.replace("__EXPERIMENT__", payload).replace("__BASE_PATH__", json.dumps(normalized_base)).replace("__MODE__", mode)
    return _decorate_experiment_page(page, mode=mode)


def _decorate_experiment_page(page: str, *, mode: str) -> str:
    """Add the research-workbench shell around the stable editor template.

    The editor/report JavaScript deliberately remains in the small template
    above.  This layer only adds the LIMO2-inspired navigation, evidence
    summary and media lightbox, so changing the visual shell cannot silently
    change the document save/publish contract.
    """

    page = page.replace("</style></head>", "</style>" + _LIMO_STYLE + _LIGHT_STYLE + "</head>", 1)
    body_marker = f'<body data-mode="{mode}"><main>'
    sidebar = """<aside id="limoSidebar" class="limo-sidebar">
  <div class="side-brand"><span class="brand-mark">RH</span><span><strong>Research Hub</strong><small>科研实验校阅</small></span></div>
  <div class="nav-kicker">研究导航</div>
  <nav id="sectionNav" aria-label="实验章节导航"></nav>
  <div id="evidenceSummary" class="side-summary"><span class="nav-kicker">证据状态</span><div class="muted">正在读取 bundle…</div></div>
</aside>"""
    page = page.replace(body_marker, f'<body data-mode="{mode}">{sidebar}<main class="limo-main">', 1)
    page = page.replace('<header class="hero">', '<header id="heroPanel" class="hero">', 1)
    page = page.replace('<div class="actions"><a id="taskLink"', '<div id="heroStats" class="hero-stats"></div><div class="actions"><a id="taskLink"', 1)
    page = page.replace('<section class="panel"><h2>实验文档（canonical Markdown）</h2>', '<section id="documentPanel" class="panel module-panel"><div class="eyebrow">RESEARCH MODULE / SOURCE</div><h2>实验文档（canonical Markdown）</h2>', 1)
    page = page.replace('<section class="panel"><h2>完整 HTML 校阅报告</h2>', '<section id="reportPanel" class="panel module-panel"><div class="eyebrow">RESEARCH MODULE / REPORT</div><h2>完整 HTML 校阅报告</h2>', 1)
    page = page.replace('<aside><section class="panel sticky">', '<aside id="evidencePanel"><section class="panel sticky"><div class="eyebrow">EVIDENCE BOUNDARY</div>', 1)
    page = page.replace('<section class="panel"><h2>章节媒体与人工校阅</h2>', '<section id="mediaPanel" class="panel module-panel"><div class="eyebrow">RESEARCH MODULE / MEDIA</div><h2>章节媒体与人工校阅</h2>', 1)
    lightbox = """<dialog id="mediaLightbox" class="media-lightbox">
  <form method="dialog" class="lightbox-toolbar"><span id="lightboxTitle">媒体预览</span><button class="secondary" aria-label="关闭媒体预览">关闭</button></form>
  <img id="lightboxImage" alt=""><p id="lightboxCaption" class="muted"></p>
</dialog>"""
    page = page.replace('</main><script id="experiment-data"', lightbox + '</main><script id="experiment-data"', 1)
    page = page.replace('</script></body></html>', '</script>' + _LIMO_SCRIPT + '</body></html>', 1)
    return page


