_LIMO_SCRIPT = r"""
<script id="research-hub-limo-script">
(()=>{const data=JSON.parse(document.getElementById('experiment-data').textContent);const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const slug=(value,index)=>'media-section-'+String(index)+'-'+String(value||'media').toLowerCase().replace(/[^\w\u4e00-\u9fff]+/g,'-').replace(/^-+|-+$/g,'');
function renderStats(){const files=data.files||[],media=data.media||[],html=files.some(f=>(f.extension||'').toLowerCase()==='.html'),score=files.some(f=>f.relative_path==='scorecard.json'||f.relative_path==='scorecard.csv'),task=Boolean(data.task_id||(data.task_links||[]).length),linked=Boolean(data.linkage||(data.task_links||[]).length);$('heroStats').innerHTML=[['文件',files.length],['媒体',media.length],['指标',score?'ready':'—'],['ClearML',task?'linked':'local']].map(([label,value])=>'<div class="hero-stat"><b>'+esc(value)+'</b><span>'+esc(label)+'</span></div>').join('');const states=[['Markdown '+(data.canonical_document_id?'可编辑':'只读'),data.canonical_document_id?'ok':'warn'],['HTML '+(html?'已生成':'缺失'),html?'ok':'warn'],['ClearML '+(task?'已绑定':'未绑定'),task?'ok':'warn'],['证据 '+(linked?'已关联':'待关联'),linked?'ok':'warn']];$('evidenceSummary').innerHTML='<span class="nav-kicker">证据状态</span>'+states.map(([label,kind])=>'<span class="badge '+kind+'">'+esc(label)+'</span>').join('')}
function renderNav(){const mediaHeadings=[...document.querySelectorAll('#media .section-title')];const mediaLinks=mediaHeadings.map((heading,index)=>{if(!heading.id)heading.id=slug(heading.textContent,index);return {id:heading.id,label:heading.textContent.trim()}});const links=[{id:'documentPanel',label:'实验文档'},{id:'reportPanel',label:'完整 HTML 报告'},{id:'evidencePanel',label:'证据与指标'},{id:'mediaPanel',label:'章节媒体'},...mediaLinks];$('sectionNav').innerHTML=links.map(item=>'<a class="section-nav-link" href="#'+esc(item.id)+'" data-target="'+esc(item.id)+'">'+esc(item.label)+'</a>').join('');$('sectionNav').querySelectorAll('a').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();const target=$(link.dataset.target);if(target){target.scrollIntoView({behavior:'smooth',block:'start'});history.replaceState(null,'','#'+target.id)}}));const observed=links.map(item=>$(item.id)).filter(Boolean);if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!visible)return;$('sectionNav').querySelectorAll('a').forEach(link=>link.classList.toggle('active',link.dataset.target===visible.target.id))},{rootMargin:'-18% 0px -62% 0px',threshold:[.05,.25,.7]});observed.forEach(target=>observer.observe(target))}}
function bindLightbox(){const dialog=$('mediaLightbox'),image=$('lightboxImage'),caption=$('lightboxCaption'),title=$('lightboxTitle');$('media').addEventListener('click',event=>{const target=event.target.closest('img');if(!target)return;image.src=target.currentSrc||target.src;image.alt=target.alt||'';title.textContent=target.alt||'媒体预览';caption.textContent=target.closest('.media-card')?.querySelector('.path')?.textContent||'';if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','')})}
renderStats();bindLightbox();const refreshNav=()=>{renderNav();};const mediaRoot=$('media');if(mediaRoot&&'MutationObserver' in window)new MutationObserver(refreshNav).observe(mediaRoot,{childList:true,subtree:true});refreshNav();})();
</script>"""


